import{_ as n,o as e,c as s,a2 as t}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"Android 桥与权限","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/android.md","filePath":"plugins/android.md","lastUpdated":1791729781000}'),r={name:"plugins/android.md"};function d(i,a,o,l,p,c){return e(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="android-桥与权限" tabindex="-1">Android 桥与权限 <a class="header-anchor" href="#android-桥与权限" aria-label="Permalink to &quot;Android 桥与权限&quot;">​</a></h1><p>通过 <code>host-&gt;java_vm</code> 与 <code>host-&gt;android_context</code> 使用 JNI，context 是当前 Activity。插件自行管理线程附着与本地引用，不跨帧保留无效 Activity 引用；非 Android 宿主可为空。</p><p>Java 桥不是冻结的跨平台 C ABI。反射签名必须核对 SDK 对应宿主的公开桥资料，不能从旧教程抄已变更重载。用户权限依 Android 清单和系统授权状态决定。</p><h2 id="常用桥" tabindex="-1">常用桥 <a class="header-anchor" href="#常用桥" aria-label="Permalink to &quot;常用桥&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>语义</th></tr></thead><tbody><tr><td><code>setStatusBarHidden(boolean)</code></td><td>Android 窗口状态栏</td></tr><tr><td><code>choosePlugin(String)</code>、<code>takePluginFd()</code></td><td>系统选择器、转移选中 ZIP fd</td></tr><tr><td><code>listPlugins(boolean)</code></td><td>原生插件清单快照</td></tr><tr><td><code>isSystemDarkTheme()</code>、<code>applyLyraTheme(boolean)</code></td><td>主题目标桥</td></tr><tr><td><code>readSiblingText(long,String,int)</code></td><td>可访问同名侧车歌词，有界读取</td></tr><tr><td><code>syncMotionArtwork(...)</code></td><td>当前动态封面叠层，有重载</td></tr><tr><td><code>clearMotionArtwork()</code></td><td>清理封面叠层</td></tr><tr><td><code>requestVerifiedResource(...)</code>、poll/cancel</td><td>通用签名/摘要校验下载</td></tr></tbody></table><p>takePluginFd 返回 -1 未选、-2 失败，非负 fd 转移给调用方，需关闭。extractMotionArtwork 的输入和输出 fd 是借用，不是同样的转移语义。</p><h2 id="外部封面与侧车" tabindex="-1">外部封面与侧车 <a class="header-anchor" href="#外部封面与侧车" aria-label="Permalink to &quot;外部封面与侧车&quot;">​</a></h2><p>“知道路径”不等于“有读取授权”。Android 版本、MediaStore 所属类型、应用私有目录和用户授权影响可访问性。插件无法运行时添加宿主清单未声明的权限。使用宿主提供的 Activity 或公开数据接口，不给每一种能力追加专有 Host 函数。</p><p>插件作者只能使用已发布桥，不能给闭源宿主自行新增 Java 方法。发布前在最低支持版本与当前系统验证反射可达性。</p><h2 id="反射签名参考" tabindex="-1">反射签名参考 <a class="header-anchor" href="#反射签名参考" aria-label="Permalink to &quot;反射签名参考&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setStatusBarHidden(Z)V</span></span>
<span class="line"><span>choosePlugin(Ljava/lang/String;)V</span></span>
<span class="line"><span>takePluginFd()I</span></span>
<span class="line"><span>listPlugins(Z)[Ljava/lang/String;</span></span>
<span class="line"><span>isSystemDarkTheme()Z</span></span>
<span class="line"><span>applyLyraTheme(Z)V</span></span>
<span class="line"><span>readSiblingText(JLjava/lang/String;I)Ljava/lang/String;</span></span>
<span class="line"><span>extractMotionArtwork(III)I</span></span>
<span class="line"><span>normalizeMotionArtwork([B)I</span></span>
<span class="line"><span>clearMotionArtwork()V</span></span>
<span class="line"><span>requestVerifiedResource(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;II)I</span></span>
<span class="line"><span>pollVerifiedResource(I)Ljava/lang/String;</span></span>
<span class="line"><span>cancelVerifiedResource(I)V</span></span>
<span class="line"><span>syncMotionArtwork(JLjava/lang/String;ZZZZFFFFFZ)V</span></span>
<span class="line"><span>syncMotionArtwork(JLjava/lang/String;ZZZZLjava/lang/String;IFFFFFZ)V</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>syncMotionArtwork 顺序：trackId、title、enabled、preferEmbedded、embedded、sidecars，扩展重载再加 directories、budget，最后 x/y/w/h/radius、playing。几何为像素。budget 为读入字节预算。extractMotionArtwork/normalizeMotionArtwork 返回 0 静态或不支持、1 动图、2 视频。</p><p>资源桥 start 返回请求 ID；poll 等待为空，完成为 <code>1\\n&lt;JSON&gt;</code>（验证索引）、<code>2\\n&lt;owned fd&gt;</code>（验证包）或 <code>-1\\n&lt;diagnostic&gt;</code>。owned fd 转移给调用方，消费或关闭；取消请求不保证你已取出的 fd 自动关闭。接口也受宿主版本限制，找不到方法时清理 JNI exception 并回退。</p><p>JNIEnv 不能跨线程缓存，worker 附着当前线程后获取自己的 JNIEnv；只在自己附着时负责 detach。删除 local refs，不把局部 jobject 当长期持有。每次获取类/方法或调用后检查异常，错误不继续调用空 method ID。</p>`,14)])])}const g=n(r,[["render",d]]);export{u as __pageData,g as default};
